import pandas as pd,numpy as np
from pymatgen.io.vasp import Poscar
x=pd.read_csv('nlo_pool.csv').set_index('candidate_id')
def calc(id,centers,ligands,cut):
 s=Poscar.from_str(x.loc[id].poscar).structure
 T=np.zeros((3,3,3)); nb=0
 for z in s:
  if z.specie.symbol in centers:
   for q in s.get_neighbors(z,cut):
    if q.specie.symbol in ligands:
     v=q.coords-z.coords; v/=np.linalg.norm(v); T+=np.einsum('i,j,k->ijk',v,v,v);nb+=1
 return abs(T).max()/s.composition.get_reduced_composition_and_factor()[1], np.linalg.norm(T)/s.composition.get_reduced_composition_and_factor()[1],nb
sets=[('c040 c041 c042 c043 c044 c045','B','S',2.1),('c050 c051 c052','Ga Zn','S',2.7),('c024 c025 c026 c027 c028 c029','Si','C',2.2),('c046 c067','Zn','S',2.7),('c057','Al','S',2.7),('c039 c063 c086','Ge','I Br Cl',3.6),('c084 c085','Sn','Cl',3.6),('c076 c077 c078','Ga','S',2.7)]
for ids,c,l,cut in sets:
 print('\n');
 for id in ids.split(): print(id,calc(id,c.split(),l.split(),cut))
